import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Activity, ArrowDownRight, ArrowLeft, ArrowRight, ArrowUpRight, Bell, CalendarDays,
  Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3,
  ClipboardCheck, Command, Compass, Download, Ellipsis, ExternalLink, FileCheck2,
  FilePlus2, Filter, Gauge, ImagePlus, LayoutDashboard, LogOut, MapPin, Menu,
  MoreHorizontal, Plus, Radio, RefreshCw, Search, Settings2, ShieldCheck,
  SlidersHorizontal, Sparkles, UserRound, UsersRound, Wrench, X, Zap,
} from 'lucide-react';
import { api, ApiError, BASES, dayLima, explainError, fmtShortId, getPage, timeLima, uploadEvidence } from './api.js';
import { demoSession, demoWorkspace, TENANTS } from './demo.js';

const NAV = [
  { key: 'resumen', label: 'Vista general', icon: LayoutDashboard, group: 'PRINCIPAL' },
  { key: 'ordenes', label: 'Órdenes de trabajo', icon: ClipboardCheck },
  { key: 'agenda', label: 'Agenda de visitas', icon: CalendarDays },
  { key: 'clientes', label: 'Clientes', icon: UsersRound, group: 'GESTIÓN' },
  { key: 'tecnicos', label: 'Equipo técnico', icon: Wrench },
  { key: 'partes', label: 'Partes y evidencias', icon: FileCheck2 },
  { key: 'actividad', label: 'Trazabilidad', icon: Activity, group: 'HERRAMIENTAS' },
  { key: 'sistema', label: 'Configuración', icon: Settings2 },
];
const PAGE_META = {
  resumen: ['Tu operación, en perspectiva.', 'Una vista clara de lo que mueve a tu equipo.'],
  ordenes: ['Órdenes de trabajo', 'Cada solicitud, de principio a fin.'],
  agenda: ['Agenda de visitas', 'El lugar donde cada minuto cuenta.'],
  clientes: ['Tus clientes', 'Personas y espacios que confían en tu servicio.'],
  tecnicos: ['Equipo técnico', 'Las personas detrás de cada visita.'],
  partes: ['Partes y evidencias', 'El trabajo habla por sí mismo.'],
  actividad: ['Trazabilidad', 'Del diagnóstico al resultado, sin perder el hilo.'],
  sistema: ['Centro de configuración', 'Tu conexión con la infraestructura de Trazora.'],
};
const MODULES = [
  { key: 'clients', service: 'ms1', path: '/clientes', result: 'clientes' },
  { key: 'technicians', service: 'ms2', path: '/tecnicos', result: 'tecnicos' },
  { key: 'orders', service: 'ms3', path: '/ordenes', result: 'ordenes' },
  { key: 'visits', service: 'ms4', path: '/visitas', result: 'visitas' },
];
const NAME = { clients: 'Clientes', technicians: 'Técnicos', orders: 'Órdenes', visits: 'Agenda' };
const safe = (value, fallback = '—') => value === null || value === undefined || value === '' ? fallback : String(value);
const tenantName = (tenant) => TENANTS.find((t) => t.id === tenant)?.name || tenant;
const statusName = (estado) => ({ ABIERTA: 'Abierta', PROGRAMADA: 'Programada', EN_ATENCION: 'En atención', FINALIZADA: 'Finalizada', PENDIENTE_DE_CIERRE: 'Por cerrar', REQUIERE_REVISITA: 'Revisita', CANCELADA: 'Cancelada', CERRADA: 'Cerrada', BORRADOR: 'Borrador', FINALIZADO: 'Finalizado', ACTIVO: 'Activo' }[estado] || safe(estado));
const statusTone = (estado) => ({ EN_ATENCION: 'blue', ABIERTA: 'amber', PROGRAMADA: 'purple', FINALIZADA: 'green', PENDIENTE_DE_CIERRE: 'green', REQUIERE_REVISITA: 'amber', CANCELADA: 'mute', CERRADA: 'green', BORRADOR: 'amber', FINALIZADO: 'green' }[estado] || 'mute');
const pad = (x) => String(x).padStart(2, '0');
const toLocalInput = (date) => `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
const initialAppointment = () => { const d = new Date(); d.setDate(d.getDate() + 1); d.setHours(10, 0, 0, 0); return toLocalInput(d); };
const todayLabel = () => new Intl.DateTimeFormat('es-PE', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'America/Lima' }).format(new Date());

function Brand({ small = false }) {
  return <div className={`brand-mark ${small ? 'brand-small' : ''}`}>
    <span className="brand-symbol"><i /><i /><i /></span>
    <span className="brand-word">trazora<span className="brand-dot">.</span>{!small && <small>FIELD SERVICE</small>}</span>
  </div>;
}
function Badge({ estado, children }) { return <span className={`state-pill state-${statusTone(estado)}`}><span className="state-dot" />{children || statusName(estado)}</span>; }
function SoftButton({ children, onClick, icon: Icon, className = '', disabled, title }) { return <button title={title} disabled={disabled} onClick={onClick} className={`soft-button ${className}`}>{Icon && <Icon size={16} strokeWidth={1.8} />}{children}</button>; }
function Empty({ icon: Icon = Compass, title, subtitle }) { return <div className="empty-state"><div className="empty-glyph"><Icon size={24} strokeWidth={1.5}/></div><strong>{title || 'No hay registros por ahora'}</strong><p>{subtitle || 'Los datos aparecerán aquí cuando estén disponibles.'}</p></div>; }
function Toast({ toast, onClose }) { return toast ? <div role="status" className={`toast toast-${toast.kind || 'success'}`}><span className="toast-symbol">{toast.kind === 'error' ? '!' : '✓'}</span><div><strong>{toast.title}</strong>{toast.message && <p>{toast.message}</p>}</div><button aria-label="Cerrar notificación" onClick={onClose}><X size={16}/></button></div> : null; }
function Metric({ label, value, text, tone, icon: Icon, chart }) { return <article className={`metric-card ${tone || ''}`}><div className="metric-label"><span>{label}</span><Icon size={18} strokeWidth={1.8}/></div><div className="metric-row"><strong>{value}</strong>{chart && <span className="metric-spark"><svg viewBox="0 0 88 34" aria-hidden="true"><path d="M0 27 C12 25 15 13 26 19 S43 10 52 13 S66 26 76 8 L88 4" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" /></svg></span>}</div><p>{text}</p></article>; }
function ErrorLine({ message }) { return message ? <div role="alert" className="form-error">{message}</div> : null; }
function Sheet({ title, subtitle, children, onClose, wide = false }) { return <div className="sheet-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}><section role="dialog" aria-modal="true" aria-label={title} className={`sheet ${wide ? 'sheet-wide' : ''}`}><div className="sheet-head"><div><div className="eyebrow">TRAZORA / ACCIÓN</div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose} aria-label="Cerrar"><X size={20}/></button></div><div className="sheet-body">{children}</div></section></div>; }
function Field({ label, children, hint }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function ActionButton({ children, onClick, type = 'button', disabled = false, loading = false, icon: Icon = ArrowRight }) { return <button type={type} className="btn-primary" onClick={onClick} disabled={disabled || loading}>{loading ? 'Procesando…' : children}<Icon size={17}/></button>; }
function Seg({ items, value, onChange }) { return <div className="segmented" role="group">{items.map((item) => <button key={item.value} type="button" className={value === item.value ? 'selected' : ''} onClick={() => onChange(item.value)}>{item.label}</button>)}</div>; }

function Login({ onReady }) {
  const [tenant, setTenant] = useState('CLIMALIMA');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  async function submit(e) {
    e.preventDefault(); setBusy(true); setError('');
    try {
      const result = await api('ms0', '/auth/login', { method: 'POST', data: { tenant_id: tenant, email, password } });
      const usuario = await api('ms0', '/usuarios/me', { token: result.token });
      if (usuario.tenant_id !== tenant) throw new Error('La sesión no corresponde a la empresa elegida.');
      setPassword(''); onReady({ ...result, usuario, demo: false });
    } catch (err) { setError(explainError(err)); setPassword(''); }
    finally { setBusy(false); }
  }
  return <main className="login-shell"><div className="login-poster"><div className="login-logo"><Brand /></div><div className="poster-content"><span className="poster-index">UNA OPERACIÓN EN MOVIMIENTO / 01</span><h1>El trabajo<br/>pasa afuera.<br/><em>El control, aquí.</em></h1><p>La plataforma que conecta a tus técnicos, tus clientes y cada decisión de campo.</p><div className="poster-map"><svg viewBox="0 0 510 225" role="img" aria-label="Ilustración conceptual de rutas de servicio"><path d="M4 134 C104 134 75 42 180 42 S300 183 408 105 S488 95 506 28" fill="none" stroke="#b6d8c3" strokeWidth="1" strokeDasharray="5 9"/><path d="M4 202 C119 156 155 194 260 108 S399 82 509 175" fill="none" stroke="#b6d8c3" strokeWidth="1" strokeDasharray="4 9"/><circle cx="180" cy="42" r="8" fill="#dff1b8"/><circle cx="260" cy="108" r="8" fill="#f59d65"/><circle cx="408" cy="105" r="8" fill="#dff1b8"/><g fill="#fff" fontSize="11"><text x="153" y="24">Visita 01</text><text x="234" y="90">En curso</text><text x="385" y="85">Cerrada</text></g></svg></div></div><div className="poster-footer"><span>TRAZABILIDAD DE PRINCIPIO A FIN</span><span>EST. 2026 — LIMA, PERÚ</span></div></div><section className="login-panel"><div className="login-top">Acceso a la plataforma <span>↗</span></div><div className="login-form-box"><div className="auth-eyebrow"><span className="online-dot"/> ACCESO EMPRESARIAL</div><h2>Bienvenido<br/><span>de nuevo.</span></h2><p className="auth-intro">Todo tu equipo, desde un solo lugar. Selecciona tu empresa para comenzar.</p><form onSubmit={submit} className="auth-form"><Field label="Tu empresa"><select value={tenant} onChange={(e)=>setTenant(e.target.value)}>{TENANTS.map(t=><option value={t.id} key={t.id}>{t.name}</option>)}</select></Field><Field label="Correo de acceso"><input type="email" required autoComplete="username" placeholder="tu@empresa.com" value={email} onChange={(e)=>setEmail(e.target.value)}/></Field><Field label="Contraseña"><input type="password" autoComplete="current-password" required placeholder="••••••••" value={password} onChange={(e)=>setPassword(e.target.value)}/></Field><ErrorLine message={error}/><ActionButton type="submit" disabled={busy} loading={busy}>Entrar a mi espacio</ActionButton></form><div className="auth-break"><span>O EXPLORA EL DISEÑO</span></div><button className="demo-button" onClick={()=>onReady(demoSession(tenant))}><Compass size={18}/> Explorar demo interactiva <ArrowUpRight size={16}/></button><p className="auth-disclaimer">La demo usa datos ficticios locales. Para trabajar con AWS debes iniciar sesión con MS0.</p></div><div className="login-bottom">TRAZORA FIELD MANAGEMENT <span>v1.0</span></div></section></main>;
}

function CreateForm({ kind, data, onSubmit, onClose, loading }) {
  const [values, setValues] = useState({ nombre: '', correo: '', telefono: '', especialidad: 'REPARACION', cliente_id: data.clients[0]?.cliente_id || '', descripcion: '', prioridad: 'MEDIA', tipo_servicio: 'REPARACION', orden_id: data.orders.find(o=>o.estado==='ABIERTA')?.orden_id || '', tecnico_id: data.technicians.find(t=>t.activo)?.tecnico_id || '', inicio: initialAppointment(), duracion: '60' });
  const set = (key, value) => setValues((s) => ({ ...s, [key]: value }));
  const titles = { clients: 'Nuevo cliente', technicians: 'Nuevo técnico', orders: 'Crear orden', visits: 'Programar visita' };
  const describe = { clients: 'Registra una nueva empresa o contacto de servicio.', technicians: 'Añade talento a tu equipo operativo.', orders: 'Convierte una solicitud en un trabajo organizado.', visits: 'Reserva un bloque real de agenda para tu técnico.' };
  return <Sheet title={titles[kind]} subtitle={describe[kind]} onClose={onClose}>
    <form className="form-grid" onSubmit={(e)=>{e.preventDefault();onSubmit(kind,values);}}>
      {(kind === 'clients' || kind === 'technicians') && <Field label={kind === 'clients' ? 'Nombre del cliente' : 'Nombre completo'}><input autoFocus required maxLength={160} placeholder={kind === 'clients' ? 'Ej. Estudio Terracota' : 'Ej. Ana Mendoza'} value={values.nombre} onChange={(e)=>set('nombre',e.target.value)}/></Field>}
      {kind === 'clients' && <><Field label="Correo electrónico"><input type="email" placeholder="contacto@empresa.com" value={values.correo} onChange={(e)=>set('correo',e.target.value)}/></Field><Field label="Teléfono"><input placeholder="999 000 000" value={values.telefono} onChange={(e)=>set('telefono',e.target.value)}/></Field></>}
      {kind === 'technicians' && <Field label="Especialidad"><select value={values.especialidad} onChange={(e)=>set('especialidad',e.target.value)}><option value="REPARACION">Reparación</option><option value="MANTENIMIENTO">Mantenimiento</option><option value="INSTALACION">Instalación</option></select></Field>}
      {kind === 'orders' && <><Field label="Cliente asociado"><select required value={values.cliente_id} onChange={(e)=>set('cliente_id',e.target.value)}><option value="">Selecciona un cliente</option>{data.clients.map(c=><option key={c.cliente_id} value={c.cliente_id}>{c.nombre}</option>)}</select></Field><Field label="Tipo de servicio"><select value={values.tipo_servicio} onChange={(e)=>set('tipo_servicio',e.target.value)}><option>REPARACION</option><option>MANTENIMIENTO</option><option>INSTALACION</option></select></Field><Field label="Prioridad"><select value={values.prioridad} onChange={(e)=>set('prioridad',e.target.value)}><option value="BAJA">Baja</option><option value="MEDIA">Media</option><option value="ALTA">Alta</option></select></Field><Field label="Descripción del trabajo"><textarea required rows={4} minLength={10} maxLength={500} placeholder="Describe el problema, el equipo y el objetivo de la visita…" value={values.descripcion} onChange={(e)=>set('descripcion',e.target.value)}/></Field></>}
      {kind === 'visits' && <><Field label="Orden abierta"><select required value={values.orden_id} onChange={(e)=>set('orden_id',e.target.value)}><option value="">Elige una orden</option>{data.orders.filter(o=>o.estado==='ABIERTA').map(o=><option value={o.orden_id} key={o.orden_id}>{o.descripcion.slice(0,48)}</option>)}</select></Field><Field label="Técnico disponible"><select required value={values.tecnico_id} onChange={(e)=>set('tecnico_id',e.target.value)}><option value="">Selecciona técnico</option>{data.technicians.filter(t=>t.activo).map(t=><option value={t.tecnico_id} key={t.tecnico_id}>{t.nombre}</option>)}</select></Field><Field label="Inicio (hora de tu dispositivo)"><input required type="datetime-local" step={1800} value={values.inicio} onChange={(e)=>set('inicio',e.target.value)}/></Field><Field label="Duración"><select value={values.duracion} onChange={(e)=>set('duracion',e.target.value)}><option value="30">30 minutos</option><option value="60">1 hora</option><option value="90">1 h 30 min</option><option value="120">2 horas</option><option value="180">3 horas</option><option value="240">4 horas</option></select></Field><div className="hint-box"><Clock3 size={16}/> La reserva exige una jornada válida y horarios libres. Si hay conflicto, AWS devolverá 409.</div></>}
      <div className="form-footer"><button type="button" className="btn-secondary" onClick={onClose}>Cancelar</button><ActionButton type="submit" loading={loading}>Guardar en {kind === 'visits' ? 'Agenda' : 'Trazora'}</ActionButton></div>
    </form>
  </Sheet>;
}

function Detail({ kind, item, data, onClose, session, onChange, notify }) {
  const [history, setHistory] = useState(null);
  const [busy, setBusy] = useState(false);
  const clientName = (id) => data.clients.find(c=>c.cliente_id===id)?.nombre || fmtShortId(id);
  const techName = (id) => data.technicians.find(t=>t.tecnico_id===id)?.nombre || fmtShortId(id);
  const title = kind==='clients' ? item.nombre : kind==='technicians' ? item.nombre : kind==='orders' ? 'Orden ' + fmtShortId(item.orden_id) : 'Visita ' + fmtShortId(item.visita_id);
  useEffect(()=>{
    setHistory(null);
    if (kind!=='orders' || session.demo) return;
    api('ms3', `/ordenes/${item.orden_id}/historial`, { token: session.token }).then(res=>setHistory(res.historial || [])).catch(()=>setHistory(null));
  }, [kind,item,session]);
  async function iniciar() {
    if (!window.confirm('¿Confirmas iniciar esta visita? Este cambio se registrará en AWS.')) return;
    setBusy(true);
    try {
      await onChange('startVisit', item);
      onClose();
    } catch (err) {notify('No se pudo iniciar', explainError(err), 'error');}
    finally {setBusy(false);}
  }
  return <Sheet title={title} subtitle="Detalle de registro · información del tenant actual" onClose={onClose}>
    <div className="detail-topline"><Badge estado={item.estado || (item.activo ? 'ACTIVO' : 'CANCELADA')}/><span className="detail-id">ID {fmtShortId(item.cliente_id || item.tecnico_id || item.orden_id || item.visita_id)}</span></div>
    <dl className="detail-dl">
      {(kind==='clients' ? [['Nombre',item.nombre],['Correo',item.correo],['Teléfono',item.telefono],['Registrado',timeLima(item.creado_en)]] : kind==='technicians' ? [['Nombre',item.nombre],['Especialidades',(item.especialidades||[]).join(' · ')],['Disponibilidad',item.activo ? 'Activo' : 'Inactivo']] : kind==='orders' ? [['Descripción',item.descripcion],['Cliente',clientName(item.cliente_id)],['Servicio',item.tipo_servicio],['Prioridad',item.prioridad],['Estado',statusName(item.estado)],['Último resultado',item.ultimo_resultado || 'Sin atención registrada'],['Creada',timeLima(item.creada_en)]] : [['Orden',fmtShortId(item.orden_id)],['Técnico',techName(item.tecnico_id)],['Inicio',timeLima(item.inicio)],['Fin',timeLima(item.fin)],['Estado',statusName(item.estado)]]).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{safe(v)}</dd></div>)}
    </dl>
    {kind==='orders' && <div className="history-card"><div className="side-section-title"><h3>Historial de eventos</h3><span>MS3</span></div>{session.demo ? <p className="muted-copy">En el modo de muestra, la trazabilidad real está desactivada.</p> : history === null ? <p className="muted-copy">No se pudo obtener el historial o aún no hay eventos registrados.</p> : history.length ? history.map((ev,i)=><div className="mini-event" key={ev.event_id||i}><span className="mini-event-dot"/><div><strong>{ev.event_type}</strong><small>{timeLima(ev.ocurrido_en)} · {ev.resultado}</small></div></div>) : <p className="muted-copy">Esta orden aún no tiene eventos.</p>}</div>}
    {kind==='visits' && item.estado==='PROGRAMADA' && <div className="detail-action"><ActionButton onClick={iniciar} loading={busy}>Iniciar visita</ActionButton></div>}
  </Sheet>;
}

function PartesView({ session, data, onError, notify, onLoad }) {
  const [visitaId, setVisitaId] = useState('');
  const [parte, setParte] = useState(null);
  const [evidencias, setEvidencias] = useState([]);
  const [diag, setDiag] = useState('');
  const [tasks, setTasks] = useState('');
  const [resultado, setResultado] = useState('PENDIENTE');
  const [busy, setBusy] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [estadoEvento, setEstadoEvento] = useState('');
  const [demoFiles, setDemoFiles] = useState([]);
  function applyPart(part, files = []) { setParte(part); setDiag(part?.diagnostico || ''); setTasks((part?.tareas || []).join('\n')); setResultado(part?.resultado || 'PENDIENTE'); setEvidencias(files); }
  async function load(create = false) {
    if (!visitaId) {notify('Elige una visita', 'Selecciona una visita antes de consultar el parte.', 'error'); return;}
    setBusy(true);setEstadoEvento('');
    try {
      if (session.demo) {
        const visita=data.visits.find(v=>v.visita_id===visitaId);
        if(!visita)throw new Error('Visita no encontrada en la demo.');
        const p = { parte_id: `demo-${visitaId}`, visita_id: visitaId, orden_id: visita.orden_id, estado: 'BORRADOR', resultado: 'PENDIENTE', version: 1, diagnostico: '', tareas: [] };
        applyPart(p,[]);notify('Borrador de muestra', 'Prueba el formulario sin modificar AWS.');return;
      }
      let res;
      try { res = await api('ms5', `/visitas/${visitaId}/partes`, {method:create?'POST':'GET', token:session.token, data:create?{}:undefined}); }
      catch(e){if(create && e instanceof ApiError && e.status===409)res=await api('ms5',`/visitas/${visitaId}/partes`,{token:session.token});else throw e;}
      const detail = await api('ms5', `/partes/${res.parte.parte_id}`, {token:session.token});
      applyPart(detail.parte,detail.evidencias||[]);
      notify('Parte recuperado', create ? 'Borrador listo para edición.' : 'Datos sincronizados con AWS.');
    } catch(e) { onError(e); } finally {setBusy(false);}
  }
  async function save() {
    if (!parte || parte.estado!=='BORRADOR')return;
    setBusy(true);
    try{
      const body={diagnostico:diag.trim(), tareas:tasks.split('\n').map(x=>x.trim()).filter(Boolean), resultado, version:Number(parte.version)};
      if(session.demo){applyPart({...parte,...body,version:Number(parte.version)+1},evidencias);notify('Guardado en demo','Este cambio solo existe en la vista de muestra.');}
      else{const res=await api('ms5',`/partes/${parte.parte_id}`,{method:'PATCH', token:session.token,data:body});applyPart(res.parte,evidencias);notify('Cambios guardados','La versión del parte se actualizó en AWS.');}
    }catch(e){onError(e);}finally{setBusy(false);}
  }
  async function handleFile(e){const file=e.target.files?.[0];e.target.value='';if(!file||!parte)return;setUploading(true);try{if(session.demo){setDemoFiles(p=>[...p,{name:file.name,type:file.type}]);notify('Foto agregada en demo','No se envió ningún archivo a S3.');}else{await uploadEvidence(session.token,parte.parte_id,file);const result=await api('ms5',`/partes/${parte.parte_id}`,{token:session.token});setEvidencias(result.evidencias||[]);notify('Evidencia confirmada','Archivo cargado en S3 y asociado al parte.');}}catch(err){onError(err);}finally{setUploading(false);}}
  async function openEvidence(evidence){try{const x=await api('ms5',`/partes/${parte.parte_id}/evidencias/${evidence.evidencia_id}/descargar`,{token:session.token});if(x.url)window.open(x.url,'_blank','noopener,noreferrer');}catch(err){onError(err);}}
  async function finish(){if(!parte||parte.estado!=='BORRADOR')return;if(!window.confirm('¿Finalizar este parte? Es irreversible y puede publicar eventos hacia Agenda y Órdenes.'))return;setBusy(true);try{if(session.demo){applyPart({...parte,estado:'FINALIZADO'},evidencias);setEstadoEvento('SIMULADO');notify('Demo finalizada','No se publicaron eventos reales.');}else{const x=await api('ms5',`/partes/${parte.parte_id}/finalizar`,{method:'POST',token:session.token,data:{version:Number(parte.version)}});setEstadoEvento(x.evento?.estado||'PENDIENTE_PUBLICACION');applyPart(x.parte,evidencias);notify('Parte finalizado',`Evento: ${x.evento?.estado||'pendiente'}. Las vistas se actualizan al refrescar.`);onLoad();}}catch(err){onError(err);}finally{setBusy(false);}}
  return <div className="parts-layout"><section className="surface parts-chooser"><div className="section-header"><div><div className="eyebrow">REGISTRO DE CAMPO</div><h2>Trabaja con una visita</h2><p>Consulta el informe asociado o inicia uno nuevo.</p></div><div className="feature-icon"><FileCheck2 size={21}/></div></div><Field label="Selecciona una visita"><select value={visitaId} onChange={(e)=>{setVisitaId(e.target.value);setParte(null);setEstadoEvento('');}}><option value="">Seleccionar visita…</option>{data.visits.map(v=><option key={v.visita_id} value={v.visita_id}>{fmtShortId(v.visita_id)} · {statusName(v.estado)} · {timeLima(v.inicio)}</option>)}</select></Field><Field label="O pega el UUID de una visita existente" hint="Útil si la visita no aparece todavía en la página cargada"><input value={visitaId} onChange={(e)=>{setVisitaId(e.target.value);setParte(null);}} placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"/></Field><div className="inline-actions"><SoftButton icon={Search} onClick={()=>load(false)} disabled={busy||!visitaId}>Consultar</SoftButton><SoftButton icon={Plus} onClick={()=>load(true)} disabled={busy||!visitaId}>Nuevo borrador</SoftButton></div><div className="hint-box"><ShieldCheck size={17}/> El tenant se identifica desde la sesión. Tu navegador nunca recibe credenciales AWS.</div></section>
    <section className="surface parts-editor"><div className="section-header"><div><div className="eyebrow">PARTE DE TRABAJO</div><h2>{parte?'Informe de atención':'El informe comienza aquí'}</h2><p>{parte?`Versión ${parte.version} · ${fmtShortId(parte.parte_id)}`:'Selecciona una visita para acceder a diagnóstico, tareas y evidencias.'}</p></div>{parte?<Badge estado={parte.estado}/>:<FilePlus2 size={24} className="muted-icon"/>}</div>
      {!parte?<Empty icon={FileCheck2} title="Sin parte seleccionado" subtitle="Cuando selecciones una visita, aquí podrás documentar todo el trabajo realizado."/>:<div className="form-grid parts-form"><Field label="Diagnóstico"><textarea rows={4} disabled={parte.estado!=='BORRADOR'} value={diag} onChange={e=>setDiag(e.target.value)} placeholder="¿Qué encontraste durante la visita?"/></Field><Field label="Tareas realizadas" hint="Una tarea por línea"><textarea rows={4} disabled={parte.estado!=='BORRADOR'} value={tasks} onChange={e=>setTasks(e.target.value)} placeholder={'Inspección de equipos\nLimpieza de filtros\nPrueba de funcionamiento'}/></Field><Field label="Resultado"><select disabled={parte.estado!=='BORRADOR'} value={resultado} onChange={e=>setResultado(e.target.value)}><option value="PENDIENTE">Pendiente</option><option value="RESUELTO">Resuelto</option><option value="REQUIERE_REVISITA">Requiere revisita</option><option value="NO_ATENDIDO">No atendido</option></select></Field><div className="evidence-panel"><div><strong>Evidencias</strong><p>PNG o JPG · hasta 5 MB · almacenamiento privado S3</p></div><label className={`upload-cta ${parte.estado!=='BORRADOR'?'is-disabled':''}`}><ImagePlus size={17}/>{uploading?'Subiendo…':'Agregar fotografía'}<input type="file" accept="image/jpeg,image/png" disabled={uploading||parte.estado!=='BORRADOR'} onChange={handleFile} hidden/></label></div>{(evidencias.length>0||demoFiles.length>0)&&<div className="evidence-list">{evidencias.map(ev=><button key={ev.evidencia_id} type="button" onClick={()=>openEvidence(ev)}><FileCheck2 size={16}/>{fmtShortId(ev.evidencia_id)} · {statusName(ev.estado)} <ExternalLink size={13}/></button>)}{demoFiles.map((ev,i)=><span key={i}><ImagePlus size={14}/>{ev.name} · Vista demo</span>)}</div>}{estadoEvento&&<div className="inline-success"><CheckCheck size={17}/> Estado de publicación: {estadoEvento}</div>}
        <div className="form-footer"><SoftButton icon={RefreshCw} onClick={()=>load(false)} disabled={busy}>Recargar</SoftButton><div className="form-footer-right"><button className="btn-secondary" disabled={busy||parte.estado!=='BORRADOR'} onClick={save}>Guardar borrador</button><ActionButton disabled={busy||parte.estado!=='BORRADOR'||resultado==='PENDIENTE'||(!session.demo && !evidencias.some(e=>e.estado==='CONFIRMADA'))} loading={busy} icon={CheckCheck} onClick={finish}>Finalizar parte</ActionButton></div></div></div>}
    </section></div>;
}

export default function App(){
  const [session,setSession]=useState(null);
  const [page,setPage]=useState('resumen');
  const [records,setRecords]=useState({clients:[],technicians:[],orders:[],visits:[]});
  const [cursors,setCursors]=useState({});
  const [loading,setLoading]=useState(false);
  const [loadMoreBusy,setLoadMoreBusy]=useState('');
  const [toast,setToast]=useState(null);
  const [search,setSearch]=useState('');
  const [modal,setModal]=useState(null);
  const [selection,setSelection]=useState(null);
  const [mobileMenu,setMobileMenu]=useState(false);
  const [palette,setPalette]=useState(false);
  const [statusFilter,setStatusFilter]=useState('TODOS');
  const [weekShift,setWeekShift]=useState(0);
  const [submitting,setSubmitting]=useState(false);
  const notify=useCallback((title,message='',kind='success')=>setToast({title,message,kind}),[]);
  const onError=useCallback((err)=>{if(err instanceof ApiError && err.status===401){setSession(null);setPage('resumen');notify('Sesión finalizada','Vuelve a iniciar sesión para continuar.','error');}else notify('No pudimos completar la operación',explainError(err),'error');},[notify]);
  const loadAll=useCallback(async(current=session)=>{if(!current)return;if(current.demo){setRecords(demoWorkspace(current.usuario.tenant_id));setCursors({});setLoading(false);return;}setLoading(true);const rs=await Promise.allSettled(MODULES.map(m=>getPage(m.service,m.path,current.token)));let failures=0,expired=false;const next={};const nextCursors={};rs.forEach((r,i)=>{const m=MODULES[i];if(r.status==='fulfilled'){next[m.key]=Array.isArray(r.value[m.result])?r.value[m.result]:[];nextCursors[m.key]=r.value.next_cursor||null;}else{failures++;next[m.key]=[];nextCursors[m.key]=null;if(r.reason instanceof ApiError&&r.reason.status===401)expired=true;}});if(expired){setSession(null);notify('Sesión vencida','Inicia sesión nuevamente.','error');return;}setRecords(next);setCursors(nextCursors);setLoading(false);if(failures)notify('Conexión parcial',`${failures} módulo(s) no respondieron. Puedes reintentar desde Actualizar.`,'error');},[session,notify]);
  useEffect(()=>{if(session)void loadAll(session);},[session,loadAll]);
  useEffect(()=>{const key=(e)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setPalette(x=>!x);}if(e.key==='Escape'){setPalette(false);setModal(null);setSelection(null);setMobileMenu(false);}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[]);
  async function logOut(){if(session&&!session.demo){try{await api('ms0','/auth/logout',{method:'POST',token:session.token,data:{}});}catch{/* salir igualmente */}}setSession(null);setPage('resumen');setRecords({clients:[],technicians:[],orders:[],visits:[]});setToast(null);}
  async function loadMore(kind){const meta=MODULES.find(m=>m.key===kind),cursor=cursors[kind];if(!meta||!cursor||session.demo)return;setLoadMoreBusy(kind);try{const r=await getPage(meta.service,meta.path,session.token,cursor);setRecords(d=>({...d,[kind]:[...d[kind],...(r[meta.result]||[])]}));setCursors(d=>({...d,[kind]:r.next_cursor||null}));}catch(e){onError(e);}finally{setLoadMoreBusy('');}}
  async function create(kind,values){setSubmitting(true);try{let service,path,body,label;switch(kind){case 'clients':service='ms1';path='/clientes';body={nombre:values.nombre.trim(),correo:values.correo.trim(),telefono:values.telefono.trim()};label='Cliente';break;case 'technicians':service='ms2';path='/tecnicos';body={nombre:values.nombre.trim(),especialidades:[values.especialidad]};label='Técnico';break;case 'orders':service='ms3';path='/ordenes';body={cliente_id:values.cliente_id,tipo_servicio:values.tipo_servicio,descripcion:values.descripcion.trim(),prioridad:values.prioridad};label='Orden';break;case 'visits':{service='ms4';path='/visitas';const start=new Date(values.inicio);if(Number.isNaN(start.getTime()))throw new Error('Fecha inválida.');if(start.getTime()<=Date.now())throw new Error('La visita debe programarse a futuro.');const minutes=start.getMinutes();if(minutes!==0&&minutes!==30)throw new Error('Elige hora exacta o media hora.');const end=new Date(start.getTime()+Number(values.duracion)*60000);body={orden_id:values.orden_id,tecnico_id:values.tecnico_id,inicio:start.toISOString().replace('.000Z','Z'),fin:end.toISOString().replace('.000Z','Z')};label='Visita';break;}default:return;}
      if(session.demo){const ids={clients:'cliente_id',technicians:'tecnico_id',orders:'orden_id',visits:'visita_id'};const key=ids[kind];const row={...body,[key]:crypto.randomUUID(),tenant_id:session.usuario.tenant_id,activo:true,estado:kind==='orders'?'ABIERTA':kind==='visits'?'PROGRAMADA':undefined,creada_en:new Date().toISOString()};setRecords(d=>({...d,[kind]:[row,...d[kind]]}));notify('Creado en modo muestra',`${label} agregado solo a esta vista. No se guardó en AWS.`);}
      else{await api(service,path,{method:'POST',token:session.token,data:body});await loadAll(session);notify('Registro creado',`${label} guardado correctamente en AWS.`);}setModal(null);
    }catch(e){onError(e);}finally{setSubmitting(false);}}
  async function change(kind,item){if(kind==='startVisit'){if(session.demo){setRecords(prev=>({...prev,visits:prev.visits.map(v=>v.visita_id===item.visita_id?{...v,estado:'EN_ATENCION'}:v)}));notify('Visita iniciada en demo','Cambio local, sin escribir en AWS.');return;}await api('ms4',`/visitas/${item.visita_id}/iniciar`,{method:'POST',token:session.token,data:{}});await loadAll(session);notify('Visita iniciada','El cambio ya figura en Agenda.');}}
  const clientsMap=useMemo(()=>Object.fromEntries(records.clients.map(c=>[c.cliente_id,c.nombre])),[records.clients]);
  const techMap=useMemo(()=>Object.fromEntries(records.technicians.map(t=>[t.tecnico_id,t.nombre])),[records.technicians]);
  const ordersMap=useMemo(()=>Object.fromEntries(records.orders.map(o=>[o.orden_id,o])),[records.orders]);
  const shown=useMemo(()=>{const key={ordenes:'orders',agenda:'visits',clientes:'clients',tecnicos:'technicians'}[page];if(!key)return [];const q=search.toLocaleLowerCase('es');return records[key].filter(x=>{const txt=[x.nombre,x.descripcion,x.orden_id,x.visita_id,x.cliente_id,x.tecnico_id].filter(Boolean).join(' ').toLocaleLowerCase('es');const okStatus=statusFilter==='TODOS'||x.estado===statusFilter;return (!q||txt.includes(q))&&okStatus;});},[records,page,search,statusFilter]);
  if(!session)return <Login onReady={s=>{setSession(s);setPage('resumen');setSearch('');}}/>;
  const active=PAGE_META[page];const counters={totalOrdenes:records.orders.length,visits:records.visits.length,active:records.visits.filter(v=>v.estado==='EN_ATENCION').length,pending:records.orders.filter(o=>['ABIERTA','PROGRAMADA','REQUIERE_REVISITA'].includes(o.estado)).length,done:records.visits.filter(v=>v.estado==='FINALIZADA').length};
  const semana=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()+(weekShift*7+i));return d;});
  return <div className="app-shell">
    <aside className={`side-nav ${mobileMenu?'menu-open':''}`}><div className="side-brand"><Brand/><button className="nav-collapse" aria-label="Cerrar menú" onClick={()=>setMobileMenu(false)}><X size={19}/></button></div><div className="nav-workspace"><span className="workspace-rail">WORKSPACE</span><div className="workspace-tenant"><span className="tenant-avatar">{tenantName(session.usuario.tenant_id).slice(0,1)}</span><div><strong>{tenantName(session.usuario.tenant_id)}</strong><small>Espacio de operaciones</small></div><ChevronDown size={15}/></div></div><nav className="nav-links" aria-label="Menú principal">{NAV.map((item,i)=>{const I=item.icon;return <div key={item.key}>{item.group&&<span className="nav-group">{item.group}</span>}<button onClick={()=>{setPage(item.key);setSearch('');setStatusFilter('TODOS');setMobileMenu(false);}} className={`nav-link ${page===item.key?'active':''}`}><I size={19} strokeWidth={1.7}/><span>{item.label}</span>{page===item.key&&<span className="nav-active-tick"/>}</button></div>;})}</nav><div className="sidebar-lower"><div className="side-connect"><span className="live-signal"><Radio size={15}/></span><div><strong>{session.demo?'Vista de muestra':'Conectado a AWS'}</strong><small>{session.demo?'Datos locales simulados':'Infraestructura · dev'}</small></div></div><button className="sidebar-profile" onClick={logOut}><span className="profile-avatar">{(session.usuario.email||'U')[0].toUpperCase()}</span><span><strong>{session.usuario.email?.split('@')[0]||'Usuario'}</strong><small>{session.usuario.rol}</small></span><LogOut size={18}/></button></div></aside>
    <div className="app-main"><header className="app-top"><div className="top-crumb"><button className="mobile-toggle" onClick={()=>setMobileMenu(true)} aria-label="Abrir menú"><Menu size={22}/></button><span>Operaciones</span><ChevronRight size={15}/><strong>{page==='resumen'?'Vista general':NAV.find(n=>n.key===page)?.label}</strong></div><div className="top-controls">{session.demo&&<span className="demo-chip"><span/> MODO DEMO</span>}<span className="today-label">{todayLabel()}</span><button className="quick-search" onClick={()=>setPalette(true)}><Search size={17}/> Buscar <kbd>⌘ K</kbd></button><button className="top-avatar" title={session.usuario.email}>{session.usuario.email?.[0]?.toUpperCase()}</button></div></header>
      <main className="page-content"><div className="page-header"><div><div className="page-breadcrumb"><span className="page-breadcrumb-square"/> {session.demo?'VISTA INTERACTIVA · DATOS FICTICIOS':'CONTROL OPERATIVO · DATOS AWS'} <span> / </span> {session.usuario.tenant_id}</div><h1>{active[0]}</h1><p>{active[1]}</p></div><div className="page-header-actions"><SoftButton icon={RefreshCw} onClick={()=>loadAll(session)} disabled={loading}>{loading?'Sincronizando…':'Actualizar'}</SoftButton>{page!=='sistema'&&page!=='actividad'&&page!=='partes'&&<ActionButton onClick={()=>setModal(({resumen:'orders',ordenes:'orders',agenda:'visits',clientes:'clients',tecnicos:'technicians'})[page])} icon={Plus}>Nuevo {({resumen:'trabajo',ordenes:'trabajo',agenda:'visita',clientes:'cliente',tecnicos:'técnico'})[page]}</ActionButton>}</div></div>
    {session.demo&&<div className="demo-banner"><Sparkles size={18}/><div><strong>Estás viendo una simulación interactiva.</strong><span> Puedes navegar, filtrar y crear registros ficticios. Para conectar AWS, cierra la demo e inicia sesión.</span></div><button onClick={logOut}>Conectar mi cuenta <ArrowRight size={15}/></button></div>}
    {page==='resumen'&&<><div className="dashboard-hero"><div className="hero-copy"><div className="hero-eyebrow"><span/> OPERACIÓN EN TIEMPO REAL</div><h2>Que nada se quede<br/>sin seguimiento<span>.</span></h2><p>Tus visitas, tu equipo y tus prioridades en una sola vista. Sin perder el pulso del día.</p><button onClick={()=>setPage('agenda')}>Explorar agenda <ArrowUpRight size={17}/></button></div><div className="hero-illustration" aria-hidden="true"><div className="orb orb-one"/><div className="orb orb-two"/><div className="route-line"><span/><span/><span/></div><div className="hero-floating-card"><span>VISITA EN CURSO</span><strong>Control de atención</strong><small><span className="small-live"/> {counters.active} en la página cargada</small></div><div className="hero-mini-marker"><MapPin size={18}/></div></div><div className="hero-number">01 / FIELD OPERATIONS</div></div>
      <div className="kpi-grid"><Metric icon={ClipboardCheck} label="Órdenes visibles" value={counters.totalOrdenes.toString().padStart(2,'0')} text="En la página cargada" chart/><Metric icon={Clock3} label="Por atender" value={counters.pending.toString().padStart(2,'0')} text="Órdenes con trabajo pendiente" tone="metric-peach"/><Metric icon={Activity} label="Visitas en curso" value={counters.active.toString().padStart(2,'0')} text="Atenciones iniciadas" tone="metric-sage"/><Metric icon={CheckCheck} label="Visitas terminadas" value={counters.done.toString().padStart(2,'0')} text="Confirmadas por Agenda" tone="metric-cream"/></div>
      <div className="dashboard-grid"><section className="surface workload-surface"><div className="section-header"><div><div className="eyebrow">CENTRO DE MANDO</div><h2>Estado de las órdenes</h2><p>Distribución de la página consultada, no total histórico.</p></div><button className="dot-menu" aria-label="Ver órdenes" onClick={()=>setPage('ordenes')}><ArrowUpRight size={18}/></button></div><div className="workload-chart"><div className="chart-ring" style={{'--done': `${records.orders.length ? records.orders.filter(o=>o.estado==='PENDIENTE_DE_CIERRE'||o.estado==='CERRADA').length/records.orders.length*100 : 0}%`}}><div><strong>{records.orders.length?Math.round(records.orders.filter(o=>o.estado==='PENDIENTE_DE_CIERRE'||o.estado==='CERRADA').length/records.orders.length*100):0}%</strong><small>para revisión</small></div></div><div className="legend"><div><i className="legend-navy"/><span>Abiertas</span><strong>{records.orders.filter(o=>o.estado==='ABIERTA').length}</strong></div><div><i className="legend-green"/><span>Por cerrar</span><strong>{records.orders.filter(o=>o.estado==='PENDIENTE_DE_CIERRE').length}</strong></div><div><i className="legend-orange"/><span>En atención</span><strong>{records.orders.filter(o=>o.estado==='EN_ATENCION').length}</strong></div><div><i className="legend-mute"/><span>Otros estados</span><strong>{records.orders.filter(o=>!['ABIERTA','PENDIENTE_DE_CIERRE','EN_ATENCION'].includes(o.estado)).length}</strong></div></div></div></section>
      <section className="surface next-surface"><div className="section-header"><div><div className="eyebrow">EN EL RADAR</div><h2>Próximas visitas</h2><p>Tu equipo, sus próximos movimientos.</p></div><button className="dot-menu" onClick={()=>setPage('agenda')} aria-label="Ir a agenda"><ArrowUpRight size={18}/></button></div><div className="next-list">{[...records.visits].sort((a,b)=>new Date(a.inicio)-new Date(b.inicio)).slice(0,4).map((v,i)=><button key={v.visita_id} className="next-item" onClick={()=>setSelection({kind:'visits',item:v})}><span className="next-index">{pad(i+1)}</span><div><strong>{ordersMap[v.orden_id]?.descripcion || `Visita ${fmtShortId(v.visita_id)}`}</strong><small>{techMap[v.tecnico_id]||'Técnico asignado'} · {timeLima(v.inicio)}</small></div><Badge estado={v.estado}/></button>)}{!records.visits.length&&<Empty title="Agenda despejada" subtitle="No hay visitas en la página cargada."/>}</div></section></div>
      <section className="surface dashboard-orders"><div className="section-header"><div><div className="eyebrow">ÚLTIMOS MOVIMIENTOS</div><h2>Órdenes recientes</h2></div><SoftButton icon={ArrowUpRight} onClick={()=>setPage('ordenes')}>Ver todas</SoftButton></div><OrdersTable rows={records.orders.slice(0,4)} clientsMap={clientsMap} onOpen={item=>setSelection({kind:'orders',item})}/></section></>}
    {page==='ordenes'&&<section className="surface table-surface"><ListToolbar label="Órdenes registradas" search={search} setSearch={setSearch} filter={statusFilter} setFilter={setStatusFilter} filters={['TODOS','ABIERTA','PENDIENTE_DE_CIERRE','EN_ATENCION','CERRADA']} count={shown.length}/><OrdersTable rows={shown} clientsMap={clientsMap} onOpen={item=>setSelection({kind:'orders',item})}/><LoadMore cursor={cursors.orders} busy={loadMoreBusy==='orders'} click={()=>loadMore('orders')}/></section>}
    {page==='clientes'&&<section className="surface table-surface"><ListToolbar label="Directorio de clientes" search={search} setSearch={setSearch} count={shown.length}/><div className="people-table">{shown.map((c,i)=><button key={c.cliente_id} onClick={()=>setSelection({kind:'clients',item:c})} className="person-line"><span className="person-avatar">{c.nombre?.[0]}</span><span className="person-text"><strong>{c.nombre}</strong><small>{c.correo||'Sin correo registrado'}</small></span><span className="person-aux">{safe(c.telefono)}</span><Badge estado={c.activo?'ACTIVO':'CANCELADA'}/><ChevronRight size={18}/></button>)}{!shown.length&&<Empty title="Sin clientes para mostrar" subtitle="Agrega tu primer cliente o cambia el término de búsqueda."/>}</div><LoadMore cursor={cursors.clients} busy={loadMoreBusy==='clients'} click={()=>loadMore('clients')}/></section>}
    {page==='tecnicos'&&<><div className="team-intro"><div><strong>Personas que hacen que todo suceda.</strong><p>Registra técnicos, consulta especialidades y organiza tu operación de campo.</p></div><div className="team-dot-pattern"/></div><div className="team-grid">{shown.map((t,i)=><button key={t.tecnico_id} className="team-card" onClick={()=>setSelection({kind:'technicians',item:t})}><span className={`team-portrait portrait-${i%4}`}><span>{t.nombre?.split(' ').map(w=>w[0]).slice(0,2).join('')}</span></span><div className="team-card-body"><div className="team-card-top"><Badge estado={t.activo?'ACTIVO':'CANCELADA'}/><ArrowUpRight size={17}/></div><h3>{t.nombre}</h3><p>{(t.especialidades||[]).map(s=>s.toLowerCase()).join(' / ')||'Sin especialidad'}</p><div className="team-card-foot"><span><Wrench size={14}/> Técnico de campo</span><span>ID {fmtShortId(t.tecnico_id)}</span></div></div></button>)}{!shown.length&&<Empty icon={Wrench} title="Todavía no hay técnicos" subtitle="Añade personal para comenzar a asignar visitas."/>}</div><LoadMore cursor={cursors.technicians} busy={loadMoreBusy==='technicians'} click={()=>loadMore('technicians')}/></>}
    {page==='agenda'&&<><section className="surface calendar-surface"><div className="section-header calendar-head"><div><div className="eyebrow">CALENDARIO OPERATIVO</div><h2>Los próximos siete días</h2><p>Horarios mostrados en la zona del navegador; en AWS se almacenan en UTC.</p></div><div className="week-controls"><button onClick={()=>setWeekShift(w=>w-1)} aria-label="Semana anterior"><ChevronLeft size={19}/></button><button onClick={()=>setWeekShift(0)}>Hoy</button><button onClick={()=>setWeekShift(w=>w+1)} aria-label="Semana siguiente"><ChevronRight size={19}/></button></div></div><div className="week-strip">{semana.map((d,i)=>{const k=dayLima(d.toISOString());const hits=records.visits.filter(v=>dayLima(v.inicio)===k).length;return <div key={k} className={`week-day ${i===0&&weekShift===0?'day-today':''}`}><span>{new Intl.DateTimeFormat('es-PE',{weekday:'short'}).format(d)}</span><strong>{d.getDate()}</strong><small>{hits ? `${hits} visita${hits>1?'s':''}` : 'Sin visitas'}</small><i className={hits?'has-visits':''}/></div>;})}</div></section><section className="surface table-surface"><ListToolbar label="Agenda de visitas" search={search} setSearch={setSearch} filter={statusFilter} setFilter={setStatusFilter} filters={['TODOS','PROGRAMADA','EN_ATENCION','FINALIZADA','CANCELADA']} count={shown.length}/><div className="visit-list">{shown.sort((a,b)=>new Date(a.inicio)-new Date(b.inicio)).map(v=><button key={v.visita_id} className="visit-card" onClick={()=>setSelection({kind:'visits',item:v})}><div className="visit-date"><strong>{new Intl.DateTimeFormat('es-PE',{day:'2-digit',timeZone:'America/Lima'}).format(new Date(v.inicio))}</strong><span>{new Intl.DateTimeFormat('es-PE',{month:'short',timeZone:'America/Lima'}).format(new Date(v.inicio))}</span></div><div className="visit-middle"><div className="visit-title"><strong>{ordersMap[v.orden_id]?.descripcion||`Visita ${fmtShortId(v.visita_id)}`}</strong><Badge estado={v.estado}/></div><p><Clock3 size={14}/>{timeLima(v.inicio,{day:undefined,month:undefined})}<span>•</span><UserRound size={14}/>{techMap[v.tecnico_id]||fmtShortId(v.tecnico_id)}</p></div><ArrowUpRight size={18}/></button>)}{!shown.length&&<Empty icon={CalendarDays} title="No hay visitas para mostrar" subtitle="Cambia el filtro o programa una nueva atención."/>}</div><LoadMore cursor={cursors.visits} busy={loadMoreBusy==='visits'} click={()=>loadMore('visits')}/></section></>}
    {page==='partes'&&<PartesView session={session} data={records} onError={onError} notify={notify} onLoad={()=>loadAll(session)}/>}
    {page==='actividad'&&<section className="surface timeline-page"><div className="section-header"><div><div className="eyebrow">ARQUITECTURA BASADA EN EVENTOS</div><h2>Una atención, varias respuestas.</h2><p>Este flujo fue probado en AWS Academy; los estados siguientes describen la integración, no son un monitor SNS en tiempo real.</p></div><span className="system-stamp"><Radio size={16}/> SNS / SQS</span></div><div className="process-track">{[{num:'01',name:'MS5 · Partes',sub:'Parte finalizado + OUTBOX',icon:FileCheck2},{num:'02',name:'SNS + SQS',sub:'Distribución desacoplada',icon:Radio},{num:'03',name:'MS4 · Agenda',sub:'Visita finalizada y confirmación',icon:CalendarDays},{num:'04',name:'MS3 · Órdenes',sub:'Historial y estado para revisión',icon:ClipboardCheck}].map((p,i)=><div className="process-step" key={p.num}><span className="process-icon"><p.icon size={22}/></span><small>PASO {p.num}</small><strong>{p.name}</strong><p>{p.sub}</p>{i<3&&<ArrowRight className="process-arrow" size={18}/>}</div>)}</div><div className="activity-note"><ShieldCheck size={22}/><p><strong>Trazabilidad real, no estados simulados.</strong> Para ver la confirmación de un evento real, abre la orden correspondiente y consulta su historial. Los eventos permanecen aislados por empresa.</p></div><div className="section-header"><div><h3>Órdenes para consultar</h3><p>Abre una orden para ver los eventos guardados en MS3.</p></div></div><OrdersTable rows={records.orders.slice(0,7)} clientsMap={clientsMap} onOpen={item=>setSelection({kind:'orders',item})}/></section>}
    {page==='sistema'&&<div className="system-layout"><section className="surface system-card"><div className="eyebrow">IDENTIDAD Y ACCESO</div><h2>Tu espacio</h2><div className="system-user"><span className="big-avatar">{session.usuario.email?.[0]?.toUpperCase()}</span><div><strong>{session.usuario.email}</strong><small>{session.usuario.rol} · {tenantName(session.usuario.tenant_id)}</small></div></div><div className="system-lines"><div><span>Empresa</span><strong>{session.usuario.tenant_id}</strong></div><div><span>Modo</span><strong>{session.demo?'Demostración':'Sesión protegida MS0'}</strong></div><div><span>Ambiente</span><strong>DEV · AWS Academy</strong></div></div><SoftButton icon={LogOut} onClick={logOut}>Cerrar sesión</SoftButton></section><section className="surface system-card"><div className="eyebrow">INTEGRACIONES</div><h2>Seis servicios. Un sistema.</h2><p className="muted-copy">Estado de configuración local de las URLs, no una prueba de disponibilidad AWS.</p><div className="api-list">{Object.entries(BASES).map(([k,v],i)=><div key={k}><span className="api-icon">MS{i}</span><strong>{['Autenticación','Clientes','Técnicos','Órdenes','Agenda','Partes'][i]}</strong><span className={v?'cfg-ready':'cfg-missing'}>{v?'Configurado':'Sin URL'}</span></div>)}</div><p className="config-tip">Las URLs se configuran con variables <code>VITE_API_MS0</code> a <code>VITE_API_MS5</code>. Nunca incluyas claves de AWS.</p></section></div>}
    <footer className="app-footer"><span>TRAZORA / FIELD SERVICE MANAGEMENT</span><span>Diseñado para que cada visita cuente · 2026</span></footer></main></div>
    {mobileMenu&&<button className="nav-overlay" onClick={()=>setMobileMenu(false)} aria-label="Cerrar menú"/>}
    {modal&&<CreateForm kind={modal} data={records} loading={submitting} onClose={()=>setModal(null)} onSubmit={create}/>}
    {selection&&<Detail key={selection.item.cliente_id||selection.item.tecnico_id||selection.item.orden_id||selection.item.visita_id} kind={selection.kind} item={selection.item} data={records} session={session} onClose={()=>setSelection(null)} onChange={change} notify={notify}/>}
    {palette&&<div className="palette-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setPalette(false);}}><div className="command-palette"><div className="palette-heading"><Search size={20}/> Ir a una sección <kbd>ESC</kbd></div>{NAV.map(item=><button key={item.key} onClick={()=>{setPage(item.key);setPalette(false);}}><item.icon size={18}/>{item.label}<ArrowRight size={16}/></button>)}</div></div>}
    <Toast toast={toast} onClose={()=>setToast(null)}/>
  </div>;
}

function OrdersTable({rows,clientsMap,onOpen}){
  return rows.length?<div className="orders-wrap"><table className="orders-table"><thead><tr><th>ORDEN</th><th>CLIENTE</th><th>PRIORIDAD</th><th>ESTADO</th><th>REGISTRO</th><th/></tr></thead><tbody>{rows.map(o=><tr key={o.orden_id} onClick={()=>onOpen(o)} tabIndex={0} onKeyDown={e=>{if(e.key==='Enter')onOpen(o);}}><td><div className="order-main"><span className="order-symbol"><ClipboardCheck size={18}/></span><div><strong>{o.descripcion}</strong><small>OT-{fmtShortId(o.orden_id)}</small></div></div></td><td>{clientsMap[o.cliente_id]||fmtShortId(o.cliente_id)}</td><td><span className={`priority priority-${(o.prioridad||'MEDIA').toLowerCase()}`}><i/>{safe(o.prioridad)}</span></td><td><Badge estado={o.estado}/></td><td className="order-date">{timeLima(o.creada_en)}</td><td className="row-more"><ArrowUpRight size={18}/></td></tr>)}</tbody></table></div>:<Empty icon={ClipboardCheck} title="Sin órdenes para mostrar" subtitle="Crea la primera orden o ajusta la búsqueda."/>;
}
function ListToolbar({label,search,setSearch,filter,setFilter,filters,count}){
  return <div className="list-toolbar"><div><div className="eyebrow">DATOS DE TU EMPRESA</div><h2>{label} <span>{count}</span></h2></div><div className="list-tools"><label className="table-search"><Search size={17}/><input placeholder="Buscar en esta página" aria-label="Buscar" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button aria-label="Limpiar" onClick={()=>setSearch('')}><X size={14}/></button>}</label>{filters&&<select className="table-filter" aria-label="Filtrar estado" value={filter} onChange={e=>setFilter(e.target.value)}>{filters.map(s=><option key={s} value={s}>{s==='TODOS'?'Todos los estados':statusName(s)}</option>)}</select>}</div></div>;
}
function LoadMore({cursor,busy,click}){return cursor?<div className="pagination"><button onClick={click} disabled={busy}>{busy?'Cargando…':'Cargar más registros'}<ArrowDownRight size={17}/></button><span>Consulta paginada · AWS</span></div>:null;}
